import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,rm,mkdir,writeFile} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-audio-audit-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de auditoria iniciou');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();
 ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}if(d.method==='Runtime.consoleAPICalled'){for(const a of d.params.args??[])if(a.value?.startsWith?.('AUDITORIA '))console.log(a.value);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 await call('Runtime.enable');
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});
 await new Promise(r=>setTimeout(r,1500));
 const result=await call('Runtime.evaluate',{awaitPromise:true,returnByValue:true,expression:`import('/docs/diario-ia/qa/auditoria-audio-20261022/analise.js').then(m=>m.run())`});
 if(result.result?.exceptionDetails)throw Error(JSON.stringify(result.result.exceptionDetails));
 const data=result.result?.result?.value;assert.ok(data,'Resultado da auditoria');
 const out='docs/diario-ia/qa-resultados/auditoria-audio';await mkdir(out,{recursive:true});
 for(const shot of data.capturas??[]){await writeFile(path.join(out,shot.nome+'.png'),Buffer.from(shot.data.split(',')[1],'base64'));delete shot.data;}
 await writeFile(path.join(out,'resultado.json'),JSON.stringify(data,null,2));
 console.log(JSON.stringify({resumo:data.resumo,amostras:data.amostras,trilha:data.trilha,diagnosticos:data.diagnosticos,latencia:data.latencia,mixagem:data.mixagem},null,2));
 assert.equal(data.resumo.resultado,'VICTORY','Batalha completa vencida por ações do bot');
 assert.deepEqual(data.resumo.derrotados,['train','robot','dinosaur','bear'],'Quatro adversários percorridos');
 assert.equal(data.diagnosticos.length,9,'Nove ataques específicos medidos');
} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
